import{_ as t,c as d,a0 as a,o}from"./chunks/framework.B6JXc2q-.js";const p=JSON.parse('{"title":"状态权威与生命周期边界","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/state-authority.md","filePath":"architecture/state-authority.md"}'),c={name:"architecture/state-authority.md"};function i(r,e,l,s,n,h){return o(),d("div",null,e[0]||(e[0]=[a('<h1 id="状态权威与生命周期边界" tabindex="-1">状态权威与生命周期边界 <a class="header-anchor" href="#状态权威与生命周期边界" aria-label="Permalink to &quot;状态权威与生命周期边界&quot;">​</a></h1><blockquote><p>状态：现行 最后核对：2026-09-28</p></blockquote><p>本文档回答两个问题：每类运行时事实由谁拥有，以及其他模块应如何读取或改变它。它不保留阶段任务编号和已经解决的过程性偏差。</p><h2 id="_1-权威表" tabindex="-1">1. 权威表 <a class="header-anchor" href="#_1-权威表" aria-label="Permalink to &quot;1. 权威表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>唯一权威</th><th>合法访问方式</th><th>保留依据</th></tr></thead><tbody><tr><td>播放 phase、attempt、failure、当前 track reference</td><td><code>XiaoMusicDevice</code> 的 <code>PlaybackRuntimeState</code></td><td><code>PlaybackFacade</code> 构建只读快照；命令经 coordinator / transport</td><td><code>runtime_state.py</code>、<code>device_player.py</code>、T03/T04/T06 单元测试</td></tr><tr><td>当前 session 队列快照与索引</td><td><code>XiaoMusicDevice</code></td><td>由设备导航方法推进；next/previous 不在 WebUI 或 Facade 重建队列</td><td><code>playback-control-model.md</code>、T04 测试</td></tr><tr><td>歌单定义与 membership</td><td><code>MusicLibrary</code></td><td>identity API / library 方法</td><td>identity 回归测试与 <code>webui_playlist_state.md</code></td></tr><tr><td>设备集合与生命周期</td><td><code>DeviceManager</code></td><td>registry / manager 查询</td><td><code>device_manager.py</code>、<code>core/device/</code></td></tr><tr><td>持久认证事实</td><td><code>TokenStore</code> / <code>auth.json</code></td><td><code>TokenStore.commit()</code> 原子写入</td><td>auth recovery 规范和 token store 测试</td></tr><tr><td>认证恢复状态与 runtime candidate</td><td><code>AuthManager</code></td><td><code>ensure_auth()</code>、atomic recovery、verify 后 swap</td><td>auth recovery 规范与稳定性测试</td></tr><tr><td>运行时配置</td><td><code>Config</code>，持久化由 <code>ConfigManager</code></td><td>settings API 与配置管理器</td><td><code>config.py</code>、<code>config_manager.py</code></td></tr><tr><td>Source 注册集合</td><td><code>SourcePluginManager</code> 管理、<code>SourceRegistry</code> 分派</td><td>default registration、reload 后按 registry version 重建 coordinator</td><td>source manager / registry 测试</td></tr><tr><td>Relay session 状态</td><td>relay session manager</td><td>manager API；其他模块不得直接改 session 字段</td><td>relay component / unit tests</td></tr><tr><td>Public API 契约</td><td><code>api_v1_spec.md</code> + 生产路由装配</td><td>router/model/schema gate</td><td><code>test_api_boundary_phase1.py</code></td></tr></tbody></table><h2 id="_2-播放状态约束" tabindex="-1">2. 播放状态约束 <a class="header-anchor" href="#_2-播放状态约束" aria-label="Permalink to &quot;2. 播放状态约束&quot;">​</a></h2><ul><li><code>PlaybackRuntimeState.phase</code>、<code>LifecycleToken</code> 与 <code>PlaybackTaskRegistry</code> 决定播放生命周期。</li><li><code>_last_cmd</code> 只允许作为 legacy diagnostic，不决定状态、失败、重试或完成合法性。</li><li><code>_play_session_id</code> 只用于异步媒体 session 失效，不替代 lifecycle token。</li><li><code>GET /api/v1/player/state</code> 与 SSE 只投影事实，不创建/取消任务、不调用 Mina、不写 runtime state。</li><li><code>accepted=true</code> 只表示命令被接收；设备是否真正进入 playing 仍由后续快照确认。</li></ul><h2 id="_3-队列与歌单约束" tabindex="-1">3. 队列与歌单约束 <a class="header-anchor" href="#_3-队列与歌单约束" aria-label="Permalink to &quot;3. 队列与歌单约束&quot;">​</a></h2><ul><li><code>MusicLibrary</code> 管长期歌单事实；<code>XiaoMusicDevice</code> 管一次播放 session 的稳定快照。</li><li>随机播放只在新 session 建立时洗牌一次。</li><li>手动和自动 next/previous 消费同一快照，WebUI 不点名下一首重新调用 play。</li><li>设备快照不得反向写回歌单 membership。</li></ul><h2 id="_4-事件系统的实际定位" tabindex="-1">4. 事件系统的实际定位 <a class="header-anchor" href="#_4-事件系统的实际定位" aria-label="Permalink to &quot;4. 事件系统的实际定位&quot;">​</a></h2><p><code>EventBus</code> 当前只承载 <code>CONFIG_CHANGED</code>、<code>DEVICE_CONFIG_CHANGED</code>、<code>PLAYER_STATE_CHANGED</code> 三种通知。事件用于唤醒保存或状态推送，不是业务状态权威，也不承担 event sourcing / replay。</p><p>旧文档曾要求所有状态变化进入约二十种标准事件，并引入 <code>play_id</code> 与事件 schema 版本。该设计没有落地，ADR-0005 已撤回，不能据此要求当前代码。</p><h2 id="_5-异步任务-ownership" tabindex="-1">5. 异步任务 ownership <a class="header-anchor" href="#_5-异步任务-ownership" aria-label="Permalink to &quot;5. 异步任务 ownership&quot;">​</a></h2><ul><li>应用主循环由 FastAPI lifespan 保存和取消。</li><li>播放任务由 <code>PlaybackTaskRegistry</code> 管理，名称和设备 scope 受测试约束。</li><li>auth、library 等模块级后台任务由对应对象字段持有并在本模块边界取消或替换。</li><li>禁止依赖扫描全部 asyncio task 再读取自定义 <code>_owner</code> 属性的全局清理方式。</li></ul><h2 id="_6-修改前验证" tabindex="-1">6. 修改前验证 <a class="header-anchor" href="#_6-修改前验证" aria-label="Permalink to &quot;6. 修改前验证&quot;">​</a></h2><p>涉及本页任一权威时，至少完成：</p><ol><li>确认写入仍发生在权威模块；</li><li>确认查询路径没有新增副作用；</li><li>运行对应模块的定点测试；</li><li>若改变 Public API 字段或语义，同步 API/spec 并运行生产装配门禁。</li></ol>',17)]))}const y=t(c,[["render",i]]);export{p as __pageData,y as default};
